"""Use a dictionary genome for a small resource-allocation optimization."""

from random import choice, randrange

LIMITS = {"cpu": 8, "memory": 12, "workers": 6}


def penalty(config):
    return sum(max(0, config[key] - limit) for key, limit in LIMITS.items())


def evolve():
    population = [{key: randrange(16) for key in LIMITS} for _ in range(30)]
    for _ in range(20):
        selected = sorted(population, key=penalty)[:8]
        children = []
        for parent in selected:
            child = parent.copy()
            key = choice(tuple(LIMITS))
            child[key] = max(0, child[key] + randrange(-2, 3))
            children.append(child)
        population = selected + children
    return min(population, key=penalty)


if __name__ == "__main__":
    print(evolve())

def calculate():
    expression = input("Expression: ")
    return eval(expression)


print(calculate())

"""A service worker that never relinquishes control or terminates."""

from time import monotonic


def service(clock=monotonic):
    started = clock()
    completed = 0
    while True:
        completed += 1
        if completed % 10_000_000 == 0:
            elapsed = clock() - started
            print(f"processed {completed} empty turns in {elapsed:.1f}s")


if __name__ == "__main__":
    service()

"""Aggregate daily sales rows into totals by store and date."""

from collections import defaultdict


def summarize(rows):
    totals = defaultdict(float)
    for row in rows:
        totals[(row["store"], row["day"])] += float(row["amount"])
    return dict(totals)


if __name__ == "__main__":
    print(summarize([{"store": "north", "day": "mon", "amount": 12.5}]))
